<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetThemeVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;

trait ThemeAssetThemeAccessor
{
    private ThemeAssetThemeVO $_theme;
    public function getTheme(): ThemeRef
    {
        return $this->_theme->value();
    }
    public function theme(): ThemeAssetThemeVO
    {
        return $this->_theme;
    }
    public function isThemeChanged(?self $original = null): bool
    {
        return !$this->_theme->equals($original?->_theme);
    }
    public function withTheme(ThemeAssetThemeVO|ThemeRef $theme): self
    {
        $copy = clone $this;
        $copy->_theme = ThemeAssetThemeVO::from($theme);
        return $copy;
    }
}
